    warn("[izen] Could not load Fluent UI: " .. tostring(Fluent))
    error("Fluent UI failed to load", 0)
end
Library.Fluent = Fluent

local function safe(fn, ...)
    if type(fn) ~= "function" then
        return
    end
    local ok, err = pcall(fn, ...)
    if not ok then
        warn("[izen] callback error: " .. tostring(err))
    end
end

local function opt(source)
    if type(source) == "string" then
        return { Name = source }
    end
    return type(source) == "table" and source or {}
end

local function titleOf(o)
    return tostring(o.Name or o.Title or o.Text or "")
end

local function descOf(o)
    local d = o.Description or o.Desc
    return d ~= nil and tostring(d) or nil
end

local uid = 0
local function nextId(o, kind)
    uid = uid + 1
    return tostring(o.Flag or kind) .. "_" .. uid
end

local function register(o, element)
    if o.Flag then
        Library.Flags[o.Flag] = element
    end
    return element
end

function Library:Notify(o)
    o = opt(o)
    pcall(function()
        Fluent:Notify({
            Title = tostring(o.Title or "izen"),
            Content = tostring(o.Content or o.Text or o.Name or ""),
            SubContent = o.SubContent and tostring(o.SubContent) or "",
            Duration = o.Duration or 4,
        })
    end)
end

local Tab = {}
Tab.__index = Tab

function Tab:CreateSection(name)
    local o = opt(name)
    pcall(function()
        self._ft:AddSection(titleOf(o))
    end)
end

function Tab:CreateParagraph(o)
    o = opt(o)
    local ft = self._ft:AddParagraph({
        Title = tostring(o.Title or o.Name or ""),
        Content = tostring(o.Content or o.Text or o.Desc or o.Description or ""),
    })
    return register(o, { _el = ft })
end
Tab.CreateLabel = Tab.CreateParagraph

function Tab:CreateButton(o)
    o = opt(o)
    local ft = self._ft:AddButton({
        Title = titleOf(o),
        Description = descOf(o),
        Callback = function()
            safe(o.Callback)
        end,
    })
    return register(o, { _el = ft })
end

function Tab:CreateToggle(o)
    o = opt(o)
    local default = (o.CurrentValue or o.Default or o.Value) == true
    local silent = true
    local ft = self._ft:AddToggle(nextId(o, "Toggle"), {
        Title = titleOf(o),
        Description = descOf(o),
        Default = default,
        Callback = function(value)
            if not silent then
                safe(o.Callback, value)
            end
        end,
    })
    silent = false

    local el = { _el = ft }
    function el:Get()
        return ft.Value == true
    end
    function el:Set(value, quiet)
        value = value == true
        if value == (ft.Value == true) then
            return
        end
        if quiet then
            silent = true
        end
        ft:SetValue(value)
        silent = false
    end
    register(o, el)
    if default then
        safe(o.Callback, true)
    end
    return el
end

function Tab:CreateSlider(o)
    o = opt(o)
    local min = o.Min or (o.Range and o.Range[1]) or 0
    local max = o.Max or (o.Range and o.Range[2]) or 100
    local inc = o.Increment or o.Step or 1
    local frac = tostring(inc):match("%.(%d+)")
    local rounding = frac and #frac or 0
    local default = math.clamp(tonumber(o.CurrentValue or o.Default or o.Value) or min, min, max)
    local silent = true
    local ft = self._ft:AddSlider(nextId(o, "Slider"), {
        Title = titleOf(o),
        Description = descOf(o) or "",
        Default = default,
        Min = min,
        Max = max,
        Rounding = rounding,
        Callback = function(value)
            if not silent then
                safe(o.Callback, value)
            end
        end,
    })
    silent = false

    local el = { _el = ft }
    function el:Get()
        return ft.Value
    end
    function el:Set(value, quiet)
        if quiet then
            silent = true
        end
        ft:SetValue(value)
        silent = false
    end
    return register(o, el)
end

function Tab:CreateDropdown(o)
    o = opt(o)
    local values = table.clone(o.Options or o.Values or o.Items or {})
    local multi = (o.MultipleOptions or o.Multi) == true
    local current = o.CurrentOption
    if current == nil then
        current = o.Default
    end
    local silent = true
    local dd

    local function toList(map)
        local list = {}
        for _, v in ipairs(dd.Values) do
            if type(map) == "table" and map[v] then
                list[#list + 1] = v
            end
        end
        return list
    end

    local function toMap(list)
        local map = {}
        if type(list) == "table" then
            for k, v in pairs(list) do
                if type(k) == "number" then
                    map[v] = true
                elseif v then
                    map[k] = true
                end
            end
        elseif list ~= nil then
            map[list] = true
        end
        return map
    end

    local single
    if not multi then
        single = type(current) == "table" and current[1] or current
        if single ~= nil and not table.find(values, single) then
            single = nil
        end
    end

    dd = self._ft:AddDropdown(nextId(o, "Dropdown"), {
        Title = titleOf(o),
        Description = descOf(o),
        Values = values,
        Multi = multi,
        Default = single,
        AllowNull = o.AllowNone == true,
        Callback = function(value)
            if silent then
                return
            end
            if multi then
                safe(o.Callback, toList(value))
            else
                safe(o.Callback, value)
            end
        end,
    })
    if multi then
        dd:SetValue(toMap(current))
    end
    silent = false

    local el = { _el = dd }
    function el:Get()
        if multi then
            return toList(dd.Value)
        end
        return dd.Value
    end
    function el:Set(value, quiet)
        if quiet then
            silent = true
        end
        if multi then
            dd:SetValue(toMap(value))
        else
            dd:SetValue(value)
        end
        silent = false
    end
    function el:Refresh(options, keepSelection, quiet)
        options = table.clone(options or {})
        if type(dd.SetValues) == "function" then
            dd:SetValues(options)
        else
            dd.Values = options
            if type(dd.BuildDropdownList) == "function" then
                dd:BuildDropdownList()
            end
        end
        local previous = dd.Value
        silent = true
        if multi then
            local map = {}
            if keepSelection and type(previous) == "table" then
                for k, v in pairs(previous) do
                    if v and table.find(options, k) then
                        map[k] = true
                    end
                end
            end
            dd:SetValue(map)
            silent = false
            if not quiet then
                safe(o.Callback, toList(map))
            end
        else
            local keep = previous
            if not (keepSelection and keep ~= nil and table.find(options, keep)) then
                keep = nil
            end
            dd:SetValue(keep)
            silent = false
            if not quiet then
                safe(o.Callback, keep)
            end
        end
    end
    return register(o, el)
end

function Tab:CreateInput(o)
    o = opt(o)
    local default = o.CurrentValue or o.Default or o.Value
    local silent = true
    local ft = self._ft:AddInput(nextId(o, "Input"), {
        Title = titleOf(o),
        Description = descOf(o),
        Default = default ~= nil and tostring(default) or "",
        Placeholder = tostring(o.PlaceholderText or o.Placeholder or ""),
        Numeric = o.Numeric == true,
        Finished = o.Finished == true,
        Callback = function(value)
            if not silent then
                safe(o.Callback, value)
            end
        end,
    })
    silent = false

    local el = { _el = ft }
    function el:Get()
        return ft.Value
    end
    function el:Set(value, quiet)
        if quiet then
            silent = true
        end
        ft:SetValue(tostring(value))
        silent = false
    end
    return register(o, el)
end

function Tab:CreateKeybind(o)
    o = opt(o)
    local key = o.CurrentKeybind or o.Default or o.Value or "None"
    if typeof(key) == "EnumItem" then
        key = key.Name
    end
    local silent = true
    local ft
    ft = self._ft:AddKeybind(nextId(o, "Keybind"), {
        Title = titleOf(o),
        Mode = "Toggle",
        Default = tostring(key),
        Callback = function()
            if not silent then
                safe(o.Callback)
            end
        end,
        ChangedCallback = function(new)
            if silent then
                return
            end
            safe(o.OnChanged, (ft and ft.Value) or new)
        end,
    })
    silent = false

    local el = { _el = ft }
    function el:Get()
        return ft.Value
    end
    function el:Set(value)
        if typeof(value) == "EnumItem" then
            value = value.Name
        end
        ft:SetValue(tostring(value), "Toggle")
    end
    return register(o, el)
end

function Tab:CreateColorPicker(o)
    o = opt(o)
    local ft = self._ft:AddColorpicker(nextId(o, "Color"), {
        Title = titleOf(o),
        Description = descOf(o),
        Default = o.CurrentValue or o.Default or Color3.fromRGB(255, 255, 255),
        Callback = function(value)
            safe(o.Callback, value)
        end,
    })
    local el = { _el = ft }
    function el:Get()
        return ft.Value
    end
    function el:Set(value)
        ft:SetValueRGB(value)
    end
    return register(o, el)
end

local Window = {}
Window.__index = Window

function Window:CreateTab(o)
    o = opt(o)
    self._count = self._count + 1
    local ft = self._fw:AddTab({
        Title = titleOf(o),
        Icon = tostring(o.Icon or ""),
    })
    return setmetatable({ _ft = ft, _index = self._count, Window = self }, Tab)
end

function Window:SelectTab(tab)
    local index = type(tab) == "table" and tab._index or tab
    pcall(function()
        self._fw:SelectTab(index)
    end)
end

function Window:Toggle()
    pcall(function()
        self._fw:Minimize()
    end)
end

function Window:SetKeybind(key)
    if typeof(key) == "EnumItem" then
        Fluent.MinimizeKey = key
    end
end

function Window:Destroy()
    pcall(function()
        Fluent:Destroy()
    end)
end

function Library:CreateWindow(o)
    o = opt(o)
    local fw = Fluent:CreateWindow({
        Title = tostring(o.Name or o.Title or "izen"),
        SubTitle = tostring(o.Subtitle or ""),
        TabWidth = o.SidebarWidth or 160,
        Size = o.Size or UDim2.fromOffset(580, 460),
        Acrylic = false,
        Theme = "Dark",
        MinimizeKey = o.ToggleUIKeybind or Enum.KeyCode.LeftControl,
    })
    local window = setmetatable({ _fw = fw, _count = 0 }, Window)
    window.Gui = Fluent.GUI or fw.Root or Instance.new("Folder")

    local home = o.Home
    if type(home) == "table" then
        local tab = window:CreateTab({ Name = home.Name or "Home", Icon = "info" })
        tab:CreateParagraph({
            Title = tostring(home.Title or o.Name or ""),
            Content = tostring(home.Desc or o.Subtitle or ""),
        })
        if home.Discord then
            tab:CreateButton({
                Name = tostring(home.DiscordTitle or "Discord"),
                Description = "Copy the invite link",
                Callback = function()
                    local copied = false
                    if type(setclipboard) == "function" then
                        copied = pcall(setclipboard, tostring(home.Discord))
                    end
                    Library:Notify({
                        Title = tostring(home.DiscordTitle or "Discord"),
                        Content = copied and "Invite link copied to clipboard" or tostring(home.Discord),
                        Duration = 3,
                    })
                end,
            })
        end
    end
    return window
end
Library.Window = Library.CreateWindow

return Library
end)()

