            local now = os.clock()
            if now - lastSellTime >= delaySec then
                lastSellTime = now
                pcall(function()
                    SellFish:FireServer("All")
                end)
            end
        end
        if Config.AutoBuyBait and Config.SelectedBuyBait ~= "" then
